+                         NULL, 0, NULL);
+    }
+  else
+    {
+      ret = wifi_command(BK7258_WIFI_CMD_OPENVELA_AP_STOP, NULL, 0,
+                         &status, sizeof(status), &result_length);
+      if (ret >= 0 && result_length != sizeof(status))
+        {
+          ret = -EPROTO;
+        }
+      else if (ret >= 0 && status != 0)
+        {
