+
+      nxmutex_lock(&g_wifi.packet_lock);
+      flags = rspin_lock_irqsave(&g_bk7258_driver_lock);
+      if (g_wifi.active_role == role &&
+          g_wifi.role_state == WIFI_ROLE_STOPPING && ret != -ETIMEDOUT)
+        {
