+        }
+      carrier = g_wifi.tx_gate;
+      rspin_unlock_irqrestore(&g_bk7258_driver_lock, flags);
+      nxmutex_unlock(&g_wifi.packet_lock);
+      wifi_set_carrier(carrier);
+    }
+
+  return ret;
+}
